def match(k):  # window size 2k+2 centered on block
    best=[]
    top,bot=13-k,14+k; left,right=12-k,13+k
    T=a[top:bot+1,left:right+1]; mask=(T!=0)
    for i in range(0,20-(bot-top)):
        for j in range(0,20-(right-left)):
